// Browse gate for the asset catalog (pure, client-safe; the server calls it again on every request).
// Owner rules (MASTER-PLAN section 2 + Asset Library): browsing a library follows the STUDIO gate of its kind:
//   sound   -> Saka and the top plan        texture / model -> the top plan only        free / Katara -> none
// It is the plan-tier rule of lib/cyrus/engine-core/asset-gate.ts (`canAsset(plan, kind, "create")`, because picking
// from a library puts new content into a project); it does NOT spend or check generation tokens (no generate gate).
// Fail closed: not signed in or an unknown plan denies. Assets ALREADY IN THE CURRENT PROJECT (source "project")
// are never gated for a signed-in owner: keeping / installing / rebuilding them is never plan-gated.
import { canAsset, type AssetDecision } from "../engine-core/asset-gate";
import type { LibraryKind, LibrarySource } from "./types";

export type BrowseViewer = { signedIn: boolean; plan: unknown };
export type BrowseDecision = { ok: true } | { ok: false; code: "sign_in" | "asset_locked" | "plan_unknown" | "bad_request"; reason: string; needs?: string };

export function canBrowse(viewer: BrowseViewer, kind: LibraryKind, source: LibrarySource): BrowseDecision {
  if (!viewer.signedIn) return { ok: false, code: "sign_in", reason: "Sign in to browse the asset library." };
  if (source === "project") return { ok: true };
  const d: AssetDecision = canAsset(viewer.plan, kind, "create");
  if (d.ok) return { ok: true };
  return { ok: false, code: d.code, reason: d.reason.replace("Creating or editing", "Browsing and using"), ...(d.needs ? { needs: d.needs } : {}) };
}

// User + project assets in the catalog: textures and sounds the customer uploaded or that live in their own
// projects (CyrusProjectAsset rows). Read through an INJECTED store (host seam: ./user-store.ts is the Prisma one,
// tests use a fake), so the catalog never imports the database itself. Pure apart from the store call.
import { assetRef, type DescriptorValue, type LibraryAsset, type LibraryKind, type LibraryLedger, type LibraryProvider } from "./types";

export type UserAssetRow = {
  id: string; projectId: string; assetKey: string; kind: string; sha256: string; size: number;
  mime: string | null; path: string | null; origin: string; provenance: unknown; createdAt: Date | string;
};
export interface UserAssetStore {
  /** every CyrusProjectAsset of every project the user owns (ownership is the store's job) */
  listForUser(userId: string): Promise<UserAssetRow[]>;
}

const words = (s: string) => s.toLowerCase().split(/[^a-z0-9]+/).filter((w) => w.length > 1);
const obj = (v: unknown): Record<string, unknown> => (v && typeof v === "object" && !Array.isArray(v) ? (v as Record<string, unknown>) : {});
const strs = (v: unknown): string[] | null => (Array.isArray(v) && v.every((x) => typeof x === "string") ? (v as string[]) : null);
const str = (v: unknown): string | null => (typeof v === "string" && v ? v : null);

const DEFAULT_LEDGER: Record<string, LibraryLedger> = {
  upload: { provenance: "uploaded by the customer", licence: null, licenceStatus: "customer upload: rights declared by the customer, not verified", author: null, original: false, derivedFrom: null },
  generated: { provenance: "generated by Cyrus for the customer's project", licence: null, licenceStatus: "generated output (not a Cyrus original; not checked against vanilla)", author: "Cyrus", original: false, derivedFrom: null },
  library: { provenance: "picked from a Cyrus library", licence: null, licenceStatus: "see the library item", author: null, original: false, derivedFrom: null },
  edited: { provenance: "edited in a Cyrus studio", licence: null, licenceStatus: "derived from an earlier asset", author: null, original: false, derivedFrom: null },
  imported: { provenance: "imported with the customer's own mod", licence: null, licenceStatus: "customer-attested import, not verified", author: null, original: false, derivedFrom: null },
};

function ledgerOf(row: UserAssetRow, p: Record<string, unknown>): LibraryLedger {
  const base = DEFAULT_LEDGER[row.origin] ?? DEFAULT_LEDGER.upload;
  const l = obj(p.ledger);
  // a stored ledger may narrow the defaults but can never claim originality for a customer asset
  return {
    provenance: str(l.provenance) ?? base.provenance, licence: str(l.licence) ?? base.licence, licenceStatus: str(l.licenceStatus) ?? base.licenceStatus,
    author: str(l.author) ?? base.author, original: false, derivedFrom: str(l.derivedFrom) ?? str(obj(p.library).itemId) ?? base.derivedFrom,
  };
}

export function userAsset(row: UserAssetRow, currentProjectId: string | null): LibraryAsset | null {
  if (row.kind !== "texture" && row.kind !== "sound") return null; // models / ui join when they have a library
  const kind = row.kind as LibraryKind;
  const source = row.projectId === currentProjectId ? "project" : "user";
  const p = obj(row.provenance);
  const q = obj(p.quality), m = obj(p.moderation);
  const descriptors: Record<string, DescriptorValue> = { origin: row.origin, bytes: row.size };
  if (typeof p.width === "number") descriptors.size = p.width;
  if (typeof q.verdict === "string") descriptors.quality = q.verdict;
  if (typeof m.status === "string") descriptors.moderation = m.status;
  if (typeof p.transparency === "string") descriptors.transparency = p.transparency;
  if (typeof p.paletteSize === "number") descriptors.paletteSize = p.paletteSize;
  const id = `${row.projectId}:${row.assetKey}`;
  return {
    kind, source, id, ref: assetRef(kind, source, id), name: str(p.name) ?? row.assetKey,
    category: str(p.category) ?? (row.origin === "upload" ? "uploads" : row.origin), subcategory: str(p.sub),
    useCases: strs(p.useCases) ?? [], tags: [...new Set([...(strs(p.tags) ?? []), ...words(row.assetKey), row.origin])],
    descriptors, ledger: ledgerOf(row, p),
    preview: kind === "texture" ? { type: "texture-asset", assetId: row.id, sha256: row.sha256, mime: row.mime } : { type: "sound-asset", assetId: row.id, sha256: row.sha256 },
    projectId: row.projectId,
  };
}

/** Newest row per (project, kind, assetKey): older rows are history, not separate assets. */
export function latestRows(rows: readonly UserAssetRow[]): UserAssetRow[] {
  const best = new Map<string, UserAssetRow>();
  const t = (r: UserAssetRow) => new Date(r.createdAt).getTime();
  for (const r of rows) {
    const k = `${r.projectId}|${r.kind}|${r.assetKey}`;
    const b = best.get(k);
    if (!b || t(r) > t(b) || (t(r) === t(b) && r.id > b.id)) best.set(k, r);
  }
  return [...best.values()].sort((a, b) => t(a) - t(b) || (a.id < b.id ? -1 : 1));
}

/** One provider per kind over the same store; the store is read once per request (memoised on the request's ctx object). */
export function userAssetProviders(store: UserAssetStore): LibraryProvider[] {
  const memo = new WeakMap<object, Promise<UserAssetRow[]>>();
  const rows = (ctx: { userId: string }) => { let p = memo.get(ctx); if (!p) { p = store.listForUser(ctx.userId); memo.set(ctx, p); } return p; };
  return (["texture", "sound"] as const).map((kind) => ({
    kind, sources: ["user", "project"] as const,
    async list(ctx, allowed) {
      if (!allowed.has("user") && !allowed.has("project")) return [];
      const out: LibraryAsset[] = [];
      for (const r of latestRows(await rows(ctx))) {
        if (r.kind !== kind) continue;
        const a = userAsset(r, ctx.projectId);
        if (a && allowed.has(a.source)) out.push(a);
      }
      return out;
    },
  }));
}
// Prisma-backed UserAssetStore (SERVER ONLY). Reads Cyrus tables only (CyrusProject by its opaque userId,
// CyrusProjectAsset by projectId): no join into Nxeon tables, so the catalog moves with Cyrus if it stands alone.
import { cyrusDb as db } from "../db";
import type { UserAssetRow, UserAssetStore } from "./user-assets";

export const MAX_USER_ASSET_ROWS = 2000;

export const prismaUserAssetStore: UserAssetStore = {
  async listForUser(userId) {
    if (!userId) return [];
    const projects = await db.cyrusProject.findMany({ where: { userId }, select: { id: true } });
    if (!projects.length) return [];
    const rows = await db.cyrusProjectAsset.findMany({
      where: { projectId: { in: projects.map((p) => p.id) }, kind: { in: ["texture", "sound"] } },
      orderBy: { createdAt: "desc" }, take: MAX_USER_ASSET_ROWS,
    });
    return rows.map((r): UserAssetRow => ({ id: r.id, projectId: r.projectId, assetKey: r.assetKey, kind: r.kind, sha256: r.sha256, size: r.size, mime: r.mime, path: r.path, origin: r.origin, provenance: r.provenance, createdAt: r.createdAt }));
  },
};
// Customer texture uploads (backend only; no UI yet). SERVER side. Flow:
//   plan gate (an upload CREATES asset content: texture = top plan, fail closed) -> project ownership ->
//   bounded decode (./png-decode.ts) -> pixel rules (alpha mode, colour count) -> quality bar (tq-1, item or tile
//   profile) -> RE-ENCODE from pixels (all metadata stripped) -> moderation hook -> storage -> CyrusProjectAsset
//   (kind texture, origin upload) on the project's head revision, provenance = the reports.
// No new tables: an upload is a library addition for that project, not a change to the mod's files, so it is
// recorded against the current head revision (a later build that uses it records its own revision).
// Every dependency is injected (host seam): storage, the project/revision store, the plan and moderation.
import { createHash } from "node:crypto";
import { assetOpForSource, canAsset } from "../engine-core/asset-gate";
import { SLOT_ID_RE } from "../engine-core/spec";
import { encodePng } from "../textures/png";
import { qualityProblems, textureQuality, type QualityProfile, type QualityReport } from "../textures/quality";
import { decodePng } from "./png-decode";

export const UPLOAD_LIMITS = {
  /** a 64x64 RGBA PNG is ~17 KB uncompressed; 256 KiB leaves room for unoptimised exports, not for payloads */
  maxBytes: 256 * 1024,
  sizes: [16, 32, 64] as const,
  maxChunks: 64,
  /** distinct opaque colours: pixel art uses a few ramps; a photo or a smooth render has thousands */
  maxColours: 256,
};
export type AlphaMode = "opaque" | "binary" | "translucent";
export const UPLOAD_MIME = "image/png";

export type ModerationVerdict = { status: "unreviewed" | "approved" | "rejected"; reason: string | null; by: string };
export type ModerationHook = (input: { userId: string; projectId: string; sha256: string; png: Buffer; width: number }) => Promise<ModerationVerdict>;
/** Documented STUB: there is no moderation provider yet. Everything is stored as `unreviewed`; nothing is approved. */
export const moderationStub: ModerationHook = async () => ({ status: "unreviewed", reason: "no moderation provider yet (stub)", by: "stub" });

export interface UploadStorage { put(key: string, bytes: Buffer, mime: string): Promise<{ path: string }> }
export type UploadDeps = {
  storage: UploadStorage;
  getProject: (projectId: string) => Promise<{ id: string; userId: string; headRevisionId: string | null } | null>;
  recordAsset: (projectId: string, a: { revisionId: string; assetKey: string; kind: "texture"; sha256: string; size: number; origin: "upload"; mime: string; path: string; provenance: Record<string, unknown> }) => Promise<{ id: string }>;
  moderate?: ModerationHook;
};
export type UploadInput = {
  userId: string; projectId: string; plan: unknown; key: string; name?: string; bytes: Buffer;
  /** "item" (default) or "tile" (block faces, swatches) for the quality bar */
  profile?: QualityProfile;
  /** allow semi-transparent pixels (default: no; the quality bar fails them anyway) */
  allowTranslucent?: boolean;
};
export type ValidatedUpload = { ok: true; png: Buffer; sha256: string; width: number; alpha: AlphaMode; colours: number; quality: QualityReport; stripped: string[]; originalSha256: string; originalBytes: number };
export type UploadError = { ok: false; code: string; error: string; quality?: QualityReport };

const sha = (b: Buffer) => createHash("sha256").update(b).digest("hex");

/** Pure validation (no gate, no storage): decode, pixel rules, quality, clean re-encode. */
export function validateTextureUpload(bytes: Buffer, opts: { profile?: QualityProfile; allowTranslucent?: boolean } = {}): ValidatedUpload | UploadError {
  if (!Buffer.isBuffer(bytes)) return { ok: false, code: "bad_request", error: "no file" };
  const d = decodePng(bytes, UPLOAD_LIMITS);
  if (!d.ok) return d;
  const px = d.raster.px; let partial = 0, clear = 0;
  const colours = new Set<number>();
  for (let i = 0; i < px.length; i += 4) {
    const a = px[i + 3];
    if (a === 0) { clear++; px[i] = px[i + 1] = px[i + 2] = 0; continue; } // normalise hidden colour under alpha 0 (no data in the RGB of clear pixels)
    if (a !== 255) partial++;
    colours.add((px[i] << 16) | (px[i + 1] << 8) | px[i + 2]);
  }
  const alpha: AlphaMode = partial ? "translucent" : clear ? "binary" : "opaque";
  if (alpha === "translucent" && !opts.allowTranslucent) return { ok: false, code: "translucent", error: `${partial} pixels are semi-transparent; use fully clear or fully solid pixels` };
  if (colours.size > UPLOAD_LIMITS.maxColours) return { ok: false, code: "too_many_colours", error: `${colours.size} distinct colours; pixel-art textures use at most ${UPLOAD_LIMITS.maxColours} (this looks like a photo or a smooth render)` };
  const quality = textureQuality(d.raster, { profile: opts.profile ?? "item" });
  if (quality.verdict === "fail") return { ok: false, code: "quality", error: qualityProblems(quality)[0] ?? "failed the texture checks", quality };
  const png = encodePng(d.raster);
  return { ok: true, png, sha256: sha(png), width: d.width, alpha, colours: colours.size, quality, stripped: d.skipped, originalSha256: sha(bytes), originalBytes: bytes.length };
}

export async function uploadTexture(input: UploadInput, deps: UploadDeps): Promise<({ ok: true; assetId: string; path: string } & Omit<ValidatedUpload, "png" | "ok">) | UploadError> {
  const gate = canAsset(input.plan, "texture", assetOpForSource("upload"));
  if (!gate.ok) return { ok: false, code: gate.code, error: gate.reason };
  if (!SLOT_ID_RE.test(input.key)) return { ok: false, code: "bad_request", error: "the texture key must be lowercase letters, digits and underscores" };
  const project = await deps.getProject(input.projectId);
  if (!project || project.userId !== input.userId) return { ok: false, code: "not_found", error: "project not found" };
  if (!project.headRevisionId) return { ok: false, code: "no_revision", error: "build the mod once before adding uploads to it" };
  const v = validateTextureUpload(input.bytes, input);
  if (!v.ok) return v;
  const moderation = await (deps.moderate ?? moderationStub)({ userId: input.userId, projectId: project.id, sha256: v.sha256, png: v.png, width: v.width });
  if (moderation.status === "rejected") return { ok: false, code: "moderation", error: moderation.reason ?? "the upload was rejected" };
  const { path } = await deps.storage.put(`cyrus/uploads/${project.id}/${v.sha256}.png`, v.png, UPLOAD_MIME);
  const row = await deps.recordAsset(project.id, {
    revisionId: project.headRevisionId, assetKey: input.key, kind: "texture", sha256: v.sha256, size: v.png.length, origin: "upload", mime: UPLOAD_MIME, path,
    provenance: {
      name: input.name ?? input.key, width: v.width, transparency: v.alpha === "opaque" ? "opaque" : "cutout", alphaMode: v.alpha, paletteSize: v.colours,
      quality: v.quality, moderation, stripped: v.stripped, original: { sha256: v.originalSha256, bytes: v.originalBytes },
      ledger: { provenance: "uploaded by the customer", licenceStatus: "customer upload: rights declared by the customer, not verified" },
    },
  });
  const { png: _png, ok: _ok, ...rest } = v;
  return { ok: true, assetId: row.id, path, ...rest };
}
