// Cyrus Sound Studio audio in the browser: WebAudio playback of PCM the studio rendered itself (the pure DSP of
// lib/cyrus/sound, run client-side) or got from the API (library previews, render-host files). One voice at a time.
// Library audio only ever comes from the gated preview route; nothing here fetches library files.
import { useCallback, useEffect, useRef, useState } from "react";
import { renderVariant } from "@/lib/cyrus/sound/render";
import { SAMPLE_RATE, type Mono } from "@/lib/cyrus/sound/dsp";
import type { SoundRole, SoundVariant } from "@/lib/cyrus/sound/spec";

type Voice = { src: AudioBufferSourceNode; t0: number; dur: number; id: string };

export function useAudio() {
  const ctx = useRef<AudioContext | null>(null);
  const voice = useRef<Voice | null>(null);
  const [playing, setPlaying] = useState<string | null>(null);
  const [loop, setLoopState] = useState(false);
  const loopRef = useRef(false);
  const ac = useCallback(() => {
    if (!ctx.current) {
      const C = window.AudioContext ?? (window as unknown as { webkitAudioContext: typeof AudioContext }).webkitAudioContext;
      try { ctx.current = new C({ sampleRate: SAMPLE_RATE }); } catch { ctx.current = new C(); }
    }
    if (ctx.current.state === "suspended") void ctx.current.resume();
    return ctx.current;
  }, []);
  const stop = useCallback(() => {
    const v = voice.current;
    voice.current = null;
    if (v) { try { v.src.onended = null; v.src.stop(); } catch { /* already stopped */ } }
    setPlaying(null);
  }, []);
  /** Play mono PCM (44.1 kHz). `id` names what plays (a variant, a layer, a library row) for the buttons. */
  const play = useCallback((pcm: Mono | Float32Array, id: string, o: { onEnd?: () => void; offsetS?: number; loop?: boolean } = {}) => {
    stop();
    if (!pcm.length) return;
    const a = ac();
    const b = a.createBuffer(1, pcm.length, SAMPLE_RATE);
    b.copyToChannel(Float32Array.from(pcm) as Float32Array<ArrayBuffer>, 0);
    const src = a.createBufferSource();
    src.buffer = b; src.loop = o.loop ?? loopRef.current; src.connect(a.destination);
    const off = Math.max(0, Math.min(b.duration - 0.001, o.offsetS ?? 0));
    src.start(0, off);
    voice.current = { src, t0: a.currentTime - off, dur: b.duration, id };
    setPlaying(id);
    src.onended = () => { if (voice.current?.src === src) { voice.current = null; setPlaying(null); } o.onEnd?.(); };
  }, [ac, stop]);
  /** Seconds into what is playing (wraps when looping), or null. */
  const position = useCallback((id?: string) => {
    const v = voice.current, a = ctx.current;
    if (!v || !a || (id && v.id !== id)) return null;
    const t = a.currentTime - v.t0;
    return v.src.loop ? t % v.dur : Math.min(t, v.dur);
  }, []);
  const setLoop = useCallback((on: boolean) => { loopRef.current = on; setLoopState(on); if (voice.current) voice.current.src.loop = on; }, []);
  /** WAV / Ogg bytes -> mono PCM at 44.1 kHz (decodeAudioData resamples to the context rate). */
  const decode = useCallback(async (bytes: ArrayBuffer): Promise<Float64Array> => {
    const a = ac();
    const buf = await a.decodeAudioData(bytes.slice(0));
    const ch = buf.getChannelData(0);
    if (buf.sampleRate === SAMPLE_RATE) return Float64Array.from(ch);
    // a context that refused 44.1 kHz: resample linearly (preview only; the render host is authoritative)
    const n = Math.round((ch.length * SAMPLE_RATE) / buf.sampleRate), out = new Float64Array(n), k = buf.sampleRate / SAMPLE_RATE;
    for (let i = 0; i < n; i++) { const p = i * k, j = Math.floor(p), f = p - j; out[i] = (ch[j] ?? 0) * (1 - f) + (ch[j + 1] ?? 0) * f; }
    return out;
  }, [ac]);
  useEffect(() => () => { stop(); void ctx.current?.close().catch(() => undefined); }, [stop]);
  return { play, stop, playing, position, loop, setLoop, decode };
}

/**
 * Render a variant in the browser with the SAME pure chain as the render host (lib/cyrus/sound/render.ts):
 * synth layers are drawn here; library layers come in as processed preview buffers (`lib:__p<i>`) or are
 * silenced by browserVariant() when library audition is off. Memoised per spec text.
 */
const memo = new Map<string, ReturnType<typeof renderVariant>>();
export function renderInBrowser(v: SoundVariant, role: SoundRole, buffers: ReadonlyMap<string, Mono>, key: string): ReturnType<typeof renderVariant> {
  const k = `${role}|${key}|${JSON.stringify(v)}`;
  const hit = memo.get(k);
  if (hit) return hit;
  let r: ReturnType<typeof renderVariant>;
  try { r = renderVariant(v, role, (id) => buffers.get(id) ?? new Float64Array(0)); }
  catch { r = { pcm: new Float64Array(0), truncated: false, gainDb: 0, peakLimited: false }; }
  if (memo.size > 160) memo.delete(memo.keys().next().value as string);
  memo.set(k, r);
  return r;
}
