export async function revertTo(projectId: string, targetId: string, opts: { message?: string; expectedHeadId?: string | null } = {}): Promise<CyrusRevision> {
  const t = await getRevision(targetId);
  if (!t || t.projectId !== projectId) throw new EngineStoreError("not_found", "revision not found in this project");
  const engine = { ...((t.engine as EngineRecord | null) ?? {}), revertOf: t.id };
  return insertRevision(projectId, {
    kind: "revert", spec: (t.spec as unknown as ModSpec | null) ?? null, manifest: manifestOf(t), modBuildId: t.modBuildId, engine,
    status: t.status as RevisionStatus, message: opts.message ?? `Revert to revision ${t.seq}`, revertOfId: t.id, expectedHeadId: opts.expectedHeadId,
  });
}

