export type RecordAssetInput = {
  revisionId: string; assetKey: string; kind: "texture" | "sound" | "model" | "ui" | "datapack" | "design" | "itemmodel" | "config"; sha256: string; size: number;
  origin: "generated" | "library" | "upload" | "edited" | "imported"; mime?: string | null; path?: string | null; provenance?: Record<string, unknown> | null;
};

export async function recordAsset(projectId: string, a: RecordAssetInput) {
  if (!/^[0-9a-f]{64}$/.test(a.sha256)) throw new EngineStoreError("bad_input", "sha256 must be 64 lowercase hex characters");
  const rev = await getRevision(a.revisionId);
  if (!rev || rev.projectId !== projectId) throw new EngineStoreError("not_found", "revision not found in this project");
  const where = { projectId_kind_assetKey_sha256: { projectId, kind: a.kind, assetKey: a.assetKey, sha256: a.sha256 } };
  // r51 storage (CYRUS_STORAGE): new bytes a customer adds (uploads, edits, imports, library copies) need room; a build's own
  // output ("generated") was gated when the build started. Bytes already in the account (same sha256) add nothing.
  const storage = await import("../storage/hooks");
  const owner = await storage.assetWriteGate(projectId, a.sha256, a.size, a.origin);
  if (owner && !owner.ok) throw new EngineStoreError(owner.code, owner.error);
  try {
    const created = await db.cyrusProjectAsset.create({
      data: { projectId, revisionId: a.revisionId, assetKey: a.assetKey, kind: a.kind, sha256: a.sha256, size: a.size, origin: a.origin, mime: a.mime ?? null, path: a.path ?? null, provenance: a.provenance ? (a.provenance as Prisma.InputJsonValue) : Prisma.DbNull },
    });
    if (owner?.ok && owner.userId) void storage.noteStorageWrite(owner.userId, owner.addBytes);
    return created;
  } catch (e) {
    if (isUniqueViolation(e)) { const row = await db.cyrusProjectAsset.findUnique({ where }); if (row) return row; }
    throw e;
  }
}
