/**
 * Reserve an identifier in the project's namespace. Idempotent: reserving the same (kind, key) again returns the
 * existing row. Glyphs get the first free codepoint from the namespace's home block (unique across all projects).
 */
export async function reserveIdentifier(projectId: string, kind: IdentifierKind, key: string): Promise<CyrusIdentifier> {
  const p = await getProject(projectId);
  if (!p) throw new EngineStoreError("not_found", "project not found");
  const built = buildIdentifier(p.namespace, kind, key);
  if (!built.ok) throw new EngineStoreError("bad_identifier", built.error);
  const where = { namespace_kind_key: { namespace: p.namespace, kind, key } };
  const existing = await db.cyrusIdentifier.findUnique({ where });
  if (existing) return existing;
  const base = { projectId, namespace: p.namespace, kind, key, fullId: built.id };
  if (kind !== "glyph") {
    try {
      return await db.cyrusIdentifier.create({ data: base });
    } catch (e) {
      if (isUniqueViolation(e)) { const row = await db.cyrusIdentifier.findUnique({ where }); if (row) return row; }
      throw e;
    }
  }
  const home = glyphHomeBlock(p.namespace);
  let tries = 0;
  for (let b = 0; b < GLYPH_BLOCKS && tries < 64; ) {
    const start = glyphBlockStart(home + b);
    const taken = new Set((await db.cyrusIdentifier.findMany({ where: { codepoint: { gte: start, lt: start + GLYPH_BLOCK } }, select: { codepoint: true } })).map((r) => r.codepoint));
    let cp = -1;
    for (let c = start; c < start + GLYPH_BLOCK; c++) if (!taken.has(c)) { cp = c; break; }
    if (cp < 0) { b++; continue; }
    tries++;
    try {
      return await db.cyrusIdentifier.create({ data: { ...base, codepoint: cp } });
    } catch (e) {
      if (isUniqueViolation(e, "codepoint")) continue; // another project took it: look again
      if (isUniqueViolation(e)) { const row = await db.cyrusIdentifier.findUnique({ where }); if (row) return row; }
      throw e;
    }
  }
  throw new EngineStoreError("glyphs_exhausted", "no free glyph codepoint");
}

