// Cyrus engine core: the plan-tier gate for custom assets (MASTER-PLAN section 2, owner decisions).
//   free, katara -> no asset studios, no asset generation
//   saka         -> SOUND (Sound Studio + Sound Library)
//   all          -> SOUND + TEXTURE (the top plan; it includes the Yakko model)
// Tiers are cumulative. The gate applies only to CREATING or EDITING asset content (a studio, a library pick, an
// upload, or Cyrus generating it automatically inside a build). Keeping, installing, rebuilding unchanged,
// exporting, importing your own mod and composing Mod Packs are NEVER gated. An unknown plan or token state
// denies creation (fail closed) but never denies keep/install/export.
// Pure + client-safe; the server must call it again on every request (the UI check is only a hint).
import type { AssetKind, AssetSource, ModSpec } from "./spec";
import { ASSET_KINDS } from "./spec";

export const ASSET_PLANS = ["free", "katara", "saka", "all"] as const;
export type AssetPlan = (typeof ASSET_PLANS)[number];
const RANK: Record<AssetPlan, number> = { free: 0, katara: 1, saka: 2, all: 3 };
export const PLAN_LABEL: Record<AssetPlan, string> = { free: "Free", katara: "Katara", saka: "Saka", all: "All models" };

/**
 * THE one place that reconciles plan spellings. The token economy calls the top plan `all`
 * (lib/cyrus/tokens/config.ts TOKEN_TIERS); the UI and the model list call it after its top model, Yakko.
 * Anything else (null, a typo, a future plan) is unknown -> null, and callers fail closed.
 */
export function normalizePlan(raw: unknown): AssetPlan | null {
  if (typeof raw !== "string") return null;
  const v = raw.trim().toLowerCase();
  if (v === "all" || v === "yakko" || v === "all models") return "all";
  if (v === "free" || v === "katara" || v === "saka") return v;
  return null;
}

/** Plan from a token state (lib/cyrus/tokens/view.ts TokenState) or anything with a `tier`. Missing state -> null (unknown). */
export const planFromTokenState = (state: { tier?: unknown } | null | undefined): AssetPlan | null => normalizePlan(state?.tier);

/**
 * Cheapest plan that may create/edit each kind. `model` and `ui` are visual assets drawn with the texture tools,
 * so they follow the Texture Studio (top plan).
 */
export const ASSET_MIN_PLAN: Readonly<Record<AssetKind, AssetPlan>> = { sound: "saka", texture: "all", model: "all", ui: "all" };

