      </div>

      {p.alerts.length ? (
        <div className="mb-5 space-y-2" role="status">
          {p.alerts.map((a, i) => <div key={i} className={`rounded-lg border px-3 py-2 text-sm ${a.level === "crit" ? "border-red-500/40 bg-red-500/10 text-red-200" : "border-amber-500/40 bg-amber-500/10 text-amber-100"}`}><b>{a.level === "crit" ? "Critical" : "Warning"}:</b> {a.text}</div>)}
        </div>
      ) : null}

      <div className="mb-6 grid grid-cols-2 gap-3 lg:grid-cols-4">
        <StatCard label="Customer storage (counted)" value={fmtBytes(total)} delta={`${n(p.accounts.count)} accounts measured`} />
        <StatCard label="Quota handed out" value={fmtBytes(p.accounts.quotaBytes)} delta={p.accounts.quotaBytes ? `${Math.round((total / p.accounts.quotaBytes) * 100)}% used` : "–"} />
        <StatCard label="Estimated disk cost / month" value={usd(p.cost.diskUsedUsd)} delta={`all used / and /tank (both hosts) at $${p.cost.usdPerGbMonth}/GB; customer data ${usd(p.cost.customerUsd)}`} />
        <StatCard label="Add-on run rate / month" value={fmtCents(p.addons.runRateCents)} delta={`${n(p.addons.active)} active · ${n(p.addons.gb)} GB · 30 d ${fmtCents(p.addons.revenue30dCents)}`} deltaGood={p.addons.pastDue === 0} />
      </div>

      <Section title="Disks and pools" sub={p.reportAt ? `live statfs + nightly report (${when(p.reportAt)})` : "live statfs on this host; node-2, ZFS pools and directory sizes need the nightly report (scripts/cyrus/storage-report.sh, not installed)"}>
        {p.disks.length ? (
          <TableWrap><table className="w-full text-sm"><thead><tr className={thCls}><th>Host</th><th>Mount / pool</th><th>Used</th><th className="hidden sm:table-cell">Size</th><th className="w-1/3">Usage</th><th className="hidden sm:table-cell">Source</th></tr></thead>
            <tbody>{p.disks.map((d) => (
              <tr key={`${d.host}${d.mount}${d.source}`} className={tdRow}><td className="whitespace-nowrap">{d.host}</td><td className="font-mono text-xs">{d.mount}</td><td className="whitespace-nowrap">{fmtBytes(d.used)}</td><td className="hidden whitespace-nowrap sm:table-cell">{fmtBytes(d.size)}</td>
                <td><div className="flex items-center gap-2"><MeterBar value={d.pct} max={100} color={d.pct >= cfg.poolCritPct ? "#ef4444" : d.pct >= cfg.poolWarnPct ? "#f59e0b" : "#6f47f5"} /><span className="w-12 text-right text-xs tabular-nums">{d.pct}%</span></div></td><td className="hidden text-xs text-slate-500 sm:table-cell">{d.source}</td></tr>
            ))}</tbody></table></TableWrap>
        ) : <Empty>No disk readings on this host.</Empty>}
        <p className="mt-2 text-xs text-slate-500">Alerts at {cfg.poolWarnPct}% (warning) and {cfg.poolCritPct}% (critical); the same thresholds run in scripts/cyrus/alert-check.sh (rules disk-*).</p>
