function go(fd: FormData, kind: "ok" | "err", msg: string): never {
  const b = String(fd.get("back") ?? "");
  const base = b.startsWith(CYRUS_ADMIN_BASE) && !b.includes("//") && b.length < 300 ? b : `${LIB}/holds`;
  const [p, q = ""] = base.split("?");
  const params = new URLSearchParams(q);
  params.delete("ok"); params.delete("err");
  params.set(kind, msg.slice(0, 300));
  redirect(`${p}?${params.toString()}`);
}

async function guard(action: CyrusAdminAction, fd: FormData): Promise<User> {
  const admin = await requireArea(CYRUS_ADMIN_ACTIONS[action]);
  if (await impersonating()) redirect("/dashboard");
  if (!(await isPreviewUser(await realUser(), "modbuilder"))) notFound();
  if (!libraryFlags().enabled) go(fd, "err", "The library backend is off (CYRUS_LIBRARY_BACKEND).");
  return admin;
}

const by = (u: User) => `owner:${u.id}`;

function entryOf(fd: FormData) {
  const id = str(fd, "entryId", 64);
