}

/** r40: tell the owners of projects that use a removed asset (they keep their own copy). Never throws. */
async function tellDependents(entryId: string, title: string, reason: string, legal: boolean) {
  try {
    const d = await moderationDeps();
    const uses = await d.records.uses.forEntry(entryId);
    const projects = [...new Set(uses.map((u) => u.projectId))].slice(0, 500);
    if (!projects.length) return;
    const owners = await cyrusDb.cyrusProject.findMany({ where: { id: { in: projects } }, select: { userId: true } });
    for (const uid of new Set(owners.map((o) => o.userId))) notifyTakedown(uid, { target: `library:${entryId}`, name: title, what: "A library asset your project uses", reason: legal ? "legal notice" : reason.slice(0, 120), counterNotice: false });
  } catch { /* notifications never block moderation */ }
}

/** Hold queue: approve (held -> published), reject (held -> removed, not legal), remove (any -> removed, optionally legal). */
export async function adminCyrusLibraryDecide(fd: FormData) {
  const decision = str(fd, "decision", 10);
  const action: CyrusAdminAction = decision === "approve" ? "library.release" : decision === "reject" ? "library.reject" : decision === "remove" ? "library.takedown" : decision === "restore" ? "library.restore" : "library.release";
  const admin = await guard(action, fd);
  const id = entryOf(fd);
  if (!id) go(fd, "err", "Bad asset id.");
  const note = str(fd, "note", 280);
  const d = await moderationDeps();
  if (decision === "approve") {
    const r = await release(d, { entryId: id, by: by(admin), note: note || undefined });
    if (!r.ok) go(fd, "err", r.error);
    await cyrusAudit({ actorId: admin.id, action, target: `library:${id}`, before: { status: "held" }, after: { status: "published" }, note });
    go(fd, "ok", `Approved: “${r.entry.title}” is published.`);
  }
  if (decision === "reject" || decision === "remove") {
    if (note.length < 3) go(fd, "err", "Give a reason (kept in the moderation log).");
    const legal = decision === "remove" && (fd.get("legal") === "1" || fd.get("legal") === "on");
    const r = await takedown(d, { entryId: id, by: by(admin), reason: decision === "reject" ? `rejected: ${note}` : note, legal });
    if (!r.ok) go(fd, "err", r.error);
    await cyrusAudit({ actorId: admin.id, action, target: `library:${id}`, after: { status: "removed", legal, dependents: r.dependents, purged: r.purged }, note });
    if (r.dependents) await tellDependents(id, r.entry.title, note, legal);
    go(fd, "ok", `${decision === "reject" ? "Rejected" : "Removed"}: “${r.entry.title}”. ${r.dependents} project(s) using it keep their own copy.`);
  }
  if (decision === "restore") {
    if (note.length < 3) go(fd, "err", "Give a reason.");
    const r = await restore(d, { entryId: id, by: by(admin), reason: note });
    if (!r.ok) go(fd, "err", r.error);
    await cyrusAudit({ actorId: admin.id, action, target: `library:${id}`, before: { status: "removed" }, after: { status: "held" }, note });
    go(fd, "ok", `Restored to the hold queue: “${r.entry.title}”.`);
  }
  go(fd, "err", "Pick approve, reject, remove or restore.");
}

