/** Real-weapon / trademark list editor: add or remove one term. Applies to NEW contributions (existing rows unchanged). */
export async function adminCyrusLibraryListEdit(fd: FormData) {
  const admin = await requireArea(CYRUS_ADMIN_ACTIONS["library.lists"]);
  if (await impersonating()) redirect("/dashboard");
  if (!(await isPreviewUser(await realUser(), "modbuilder"))) notFound();
  const list = str(fd, "list", 20) as FilterListName;
  if (!FILTER_LIST_NAMES.includes(list)) go(fd, "err", "Pick a list.");
  const op = str(fd, "op", 10);
  const term = str(fd, "term", 60).toLowerCase();
  if (!validFilterTerm(term)) go(fd, "err", "A term is 1-60 letters, digits, spaces or . ' & + -");
  const row = await db.setting.findUnique({ where: { key: FILTER_LISTS_SETTING } });
  const ov = parseFilterOverrides(row?.value);
  const cur = { add: [...(ov[list]?.add ?? [])], remove: [...(ov[list]?.remove ?? [])] };
  const before = JSON.parse(JSON.stringify(cur));
  if (op === "add") { cur.remove = cur.remove.filter((t) => t !== term); if (!cur.add.includes(term)) cur.add.push(term); }
  else if (op === "remove") { cur.add = cur.add.filter((t) => t !== term); if (!cur.remove.includes(term)) cur.remove.push(term); }
  else if (op === "reset") { cur.add = cur.add.filter((t) => t !== term); cur.remove = cur.remove.filter((t) => t !== term); }
  else go(fd, "err", "Pick add, remove or reset.");
  const next = { ...ov, [list]: cur };
  const value = JSON.stringify(next);
  await db.setting.upsert({ where: { key: FILTER_LISTS_SETTING }, update: { value }, create: { key: FILTER_LISTS_SETTING, value } });
  await cyrusAudit({ actorId: admin.id, action: "library.lists", target: `setting:${FILTER_LISTS_SETTING}:${list}`, before, after: cur, note: `${op} ${term}` });
  go(fd, "ok", `${list === "realWeapons" ? "Real-weapon" : "Trademark"} list: ${op} “${term}”. Applies to new contributions.`);
}

