/** GET /api/cyrus/assets/v1/projects?root=<rootBuildId>: the mod's assets, the viewer's studio access and pack status. */
export const handleProjectAssets = (req: Request, deps: StudioApiDeps) => run(deps, { key: "read", max: 120 }, async ({ viewer }) => {
  const root = new URL(req.url).searchParams.get("root") ?? "";
  need(RE.root.test(root), "root must be a build id");
  const view = await projectAssets(deps.service, viewer.userId, root);
  const sel = deps.sound?.renderHost();
  const cleared = deps.sound?.libraryCleared() ?? false;
  const sound = {
    libraryCleared: cleared,
    audition: auditionDecision({ cleared, plan: view.access.plan }),
    render: sel?.ok ? sel.host.id : null, renderOff: sel && !sel.ok ? sel.reason : sel ? null : "sound rendering is not wired here",
    candidates: deps.soundCandidates?.id ?? null,
  };
  // manifest metadata (never audio) of every library sound the project's sound sets use: lengths for the timeline,
  // loudness, a readable name and the 64-level outline the waveform draws when library audition is off
  const ids = new Set<string>();
  for (const st of view.soundSets) for (const sp of [st.spec, ...st.history.map((h) => h.spec), ...st.candidates.map((c) => c.spec)]) for (const id of libraryIdsOf(sp)) ids.add(id);
  const soundLibrary = Object.fromEntries([...ids].slice(0, 200).flatMap((id) => { const ls = librarySound(id); return ls ? [[id, { duration: ls.duration, lufs: ls.lufs, prefix: ls.prefix, category: ls.category, peaks: libraryPeaks(id) }]] : []; }));
  return json(200, { ...view, uploads: !!deps.uploads, candidates: deps.candidates.id, sound, soundLibrary });
});

type P = { projectId?: string; key?: string; requestId?: string; assetId?: string };
const params = (p: P, ...names: (keyof P)[]) => {
  for (const n of names) {
    const v = p[n] ?? "";
    const re = n === "projectId" ? RE.project : n === "key" ? RE.key : RE.id;
    need(re.test(v), `${n} is not valid`);
  }
  return p as Required<P>;
};

/** GET .../projects/:projectId/textures/:key/revisions: the texture's history (every revision keeps its doc + quality). */
export const handleTextureHistory = (_req: Request, p: P, deps: StudioApiDeps) => run(deps, { key: "read", max: 120 }, async ({ viewer }) => {
  const { projectId, key } = params(p, "projectId", "key");
  const proj = await deps.service.store.project(projectId);
  if (!proj || proj.userId !== viewer.userId) throw new StudioError(404, "not_found", "Project not found.");
  const chain = proj.rootBuildId ? await deps.service.chain(viewer.userId, proj.rootBuildId) : null;
  const t = resolveTextures(await deps.service.store.assets(projectId), textureCandidateIds(chain), soundCandidateIds(chain)).find((x) => x.key === key);
  if (!t) throw new StudioError(404, "not_found", `No texture called ${key} in this mod.`);
  const revs = await deps.service.store.revisions(projectId);
  const seq = new Map(revs.map((r) => [r.id, r.seq]));
  return json(200, { key, history: t.history.map((h) => ({ ...h, revisionSeq: seq.get(h.revisionId) ?? null, quality: docQuality(h.doc) })) });
});

