function LibPlay({ item, audio, caps, toast }: { item: LibraryItem; audio: ReturnType<typeof useAudio>; caps: NonNullable<AssetsView["sound"]> | { audition: { library: boolean; reason: string | null } }; toast: (m: string, e?: boolean) => void }) {
  const id = `lib:${item.id}`;
  const [loading, setLoading] = useState(false);
  const on = audio.playing === id;
  const go = async () => {
    if (on) { audio.stop(); return; }
    if (!caps.audition.library) { toast(caps.audition.reason ?? "Library audition is off.", true); return; }
    setLoading(true);
    try {
      const pcm = await audio.decode(await studioApi.preview(auditionRequest(item.id, item.sound?.duration ?? 1)));
      audio.play(pcm, id, { loop: false });
    } catch (e) { toast(e instanceof ApiError ? e.message : "No preview.", true); }
    finally { setLoading(false); }
  };
  return <button type="button" className={`sd-pb ${on ? "on" : ""} ${caps.audition.library ? "" : "off"}`} onClick={() => void go()} aria-label={caps.audition.library ? `Audition ${item.sound?.prefix ?? item.name}` : "Library audition is off (licence)"} title={caps.audition.library ? "Audition a short preview" : caps.audition.reason ?? ""} data-testid="lib-audition" aria-disabled={!caps.audition.library}><SI n={loading ? "minus" : on ? "stop" : caps.audition.library ? "play" : "lock"} /></button>;
}

