export class ApiError extends Error { constructor(public status: number, public code: string, message: string, public body: Record<string, unknown>) { super(message); } }

async function call<T>(path: string, init?: RequestInit): Promise<T> {
  const r = await fetch(API + path, { cache: "no-store", ...init, headers: { ...(init?.body && !(init.body instanceof FormData) ? { "content-type": "application/json" } : {}), ...(init?.headers ?? {}) } });
