// The customer app's rail (desktop) / tab bar (phone). Links are host-aware: on cyrus.my they use the public paths.
import { usePathname } from "next/navigation";
import { IconHome, IconPlus, IconStack, IconStudio, IconUser } from "./icons";

export type NavHrefs = { home: string; new: string; projects: string; studio: string; account: string };

export function AppNav({ hrefs }: { hrefs: NavHrefs }) {
  const path = usePathname() || "";
  const at = (k: keyof NavHrefs) => {
    const internal = { home: "/dashboard/cyrus/app", new: "/dashboard/cyrus/app/new", projects: "/dashboard/cyrus/app/projects", studio: "/dashboard/cyrus", account: "/dashboard/cyrus/app/account" }[k];
    if (k === "home") return path === internal || path === hrefs.home;
    if (k === "studio") return false;
    return path.startsWith(internal) || path.startsWith(hrefs[k]);
  };
  const item = (k: keyof NavHrefs, label: string, Icon: typeof IconHome, desk = false) => (
    <a key={k} href={hrefs[k]} className={`cx-nav-a${desk ? " cx-desk" : ""}`} aria-current={at(k) ? "page" : undefined} data-tour={`nav-${k}`}>
      <Icon />{label}
    </a>
  );
  return (
    <nav aria-label="Cyrus" style={{ display: "contents" }}>
      {item("home", "Home", IconHome)}
      {item("new", "New mod", IconPlus)}
      {item("projects", "Projects", IconStack)}
      {item("studio", "Studio", IconStudio)}
      {item("account", "Account", IconUser)}
    </nav>
  );
}
