// Small server-safe UI pieces shared by the customer app pages (r39).
import type { FlightBadge } from "@/lib/cyrus/app/view";
import { CYRUS_STATUS_LABEL } from "@/lib/cyrus/models";

export function Card({ title, icon, aside, children, className = "", d = 0, tour }: { title: string; icon?: React.ReactNode; aside?: React.ReactNode; children: React.ReactNode; className?: string; d?: number; tour?: string }) {
  return (
    <section className={`cx-card cx-reveal ${className}`} style={{ ["--d" as string]: `${d}s` }} aria-label={title} data-tour={tour}>
      <div className="cx-card-h">{icon ? <span className="cx-glyph">{icon}</span> : null}<h2 className="cx-h2">{title}</h2>{aside ? <span className="cx-aside">{aside}</span> : null}</div>
      {children}
    </section>
  );
}

const SHORT: Record<FlightBadge["tone"], string | null> = { ok: "Flight passed", bad: "Flight failed", warn: "Flight incomplete", wait: "In flight", none: null };
/** Test Flight pill. `short` keeps rows tidy: the full label + reason go in the tooltip. */
export function Flight({ f, short = false }: { f: FlightBadge | null; short?: boolean }) {
  if (!f) return <span className="cx-pill cx-none">No build yet</span>;
  const text = (short && SHORT[f.tone]) || f.label;
  return <span className={`cx-pill cx-${f.tone}`} title={[f.label, f.detail].filter(Boolean).join(": ") || undefined}>{text}</span>;
}

const STATUS: Record<string, [string, string]> = {
  succeeded: ["ok", "Built"], failed: ["bad", "Failed"], cancelled: ["none", "Cancelled"], queued: ["wait", "Queued"],
};
export function BuildStatus({ status }: { status: string }) {
  const [tone, label] = STATUS[status] ?? ["wait", CYRUS_STATUS_LABEL[status] ?? "Building"];
  return <span className={`cx-pill cx-${tone}`}>{label}</span>;
}

export function Empty({ children, action }: { children: React.ReactNode; action?: React.ReactNode }) {
  return <div className="cx-empty"><div>{children}</div>{action}</div>;
}

