  if (!isNamespace(input.namespace)) return { ok: false, error: `"${input.namespace}" is not a reserved nx_ namespace` };
  if (!TEX_KEY.test(input.key) || !SLOT_ID_RE.test(input.key)) return { ok: false, error: "the texture key must be 2-32 lowercase letters, digits and underscores, starting with a letter" };
  const item = input.itemId ? libraryTexture(input.itemId) : null;
  if (input.itemId && !item) return { ok: false, error: `unknown library texture ${input.itemId}` };
  const t = template(item?.templateId ?? input.templateId ?? "");
  if (!t) return { ok: false, error: `unknown texture template ${String(input.templateId)}` };
  const base = item ? (Object.fromEntries(Object.entries(item.ramps).filter(([, v]) => v)) as TemplateVariant) : t.variants[0];
  const inst = instantiate(t, { name: input.key, ramps: { ...base, ...(input.ramps ?? {}) }, dna: input.dna ?? item?.dna });
  if (!inst.ok) return inst;
  const quality = textureQuality(render(inst.spec), { profile: t.profile, tileable: t.tileable, framed: t.framed });
  if (quality.verdict === "fail") return { ok: false, error: `this combination fails the texture checks: ${qualityProblems(quality)[0]}` };
  const path = `${t.category === "blocks" ? "block" : "item"}/${input.key}`;
  const built = buildIdentifier(input.namespace, "model", path);
  if (!built.ok) return { ok: false, error: built.error };
  const r = await reserve("model", path);
  if (r.fullId !== built.id) return { ok: false, error: `reserved ${r.fullId}, expected ${built.id} (wrong project namespace?)` };

export type StudioViewer = { userId: string; user?: unknown; preview: boolean };
export type UploadStore = UploadStorage & { get(path: string): Promise<Buffer | null> };
export type StudioApiDeps = {
  viewer: () => Promise<StudioViewer | null>;
  service: StudioServiceDeps;
  candidates: CandidateBackend;
  catalog: CatalogDeps;
  rateLimit: (key: string, max: number, windowMs: number) => { ok: boolean; retryAfterSec?: number };
  /** null = uploads are not switched on (no production upload storage yet) */
  uploads: UploadStore | null;
  /** Sound Studio (R1b): licence flag + render host, the candidate backend and the audition cache. Absent = sound
   *  endpoints answer 503 (older wiring / texture-only tests). */
  sound?: SoundDeps;
  soundCandidates?: SoundCandidateBackend;
  previewCache?: PreviewCache;
};

const H = { "cache-control": "no-store", "x-robots-tag": "noindex" };
export const json = (status: number, body: unknown) => Response.json(body, { status, headers: H });
export const NO_STORE = H;
export const NOT_FOUND = () => json(404, { error: "Not found" });
export const RE = {
  root: /^[A-Za-z0-9_-]{1,64}$/, project: /^cp[0-9a-f]{20}$/, key: /^[a-z][a-z0-9_]{1,31}$/, id: /^[A-Za-z0-9_-]{1,64}$/,
  ref: /^(sound|texture|model)\/(builtin|user|project)\/[A-Za-z0-9_:.-]{1,120}$/,
};
const MAX_BODY = 512 * 1024;

export async function readJson(req: Request): Promise<Record<string, unknown>> {
  const len = Number(req.headers.get("content-length") ?? 0);
  if (len > MAX_BODY) throw new StudioError(413, "too_large", "That request is too large.");
  const text = await req.text();
  if (text.length > MAX_BODY) throw new StudioError(413, "too_large", "That request is too large.");
  try { const v = JSON.parse(text || "{}"); if (v && typeof v === "object" && !Array.isArray(v)) return v; } catch { /* fallthrough */ }
  throw new StudioError(400, "bad_json", "Send a JSON object.");
}

export type Ctx = { deps: StudioApiDeps; viewer: StudioViewer };
/** viewer + rate limit + error mapping around a handler body. */
export async function run(deps: StudioApiDeps, limit: { key: string; max: number }, body: (c: Ctx) => Promise<Response>): Promise<Response> {
  const viewer = await deps.viewer().catch(() => null);
  if (!viewer) return NOT_FOUND();
  const rl = deps.rateLimit(`${limit.key}:${viewer.userId}`, limit.max, 60_000);
  if (!rl.ok) return json(429, { error: `Too many requests. Wait ${rl.retryAfterSec ?? 30}s.`, code: "rate_limited" });
  try {
    return await body({ deps, viewer });
  } catch (e) {
  const sp = useSearchParams();
  const partKey = sp?.get("part") ?? null;
  const part = partKey && partKey in PART_META ? PART_META[partKey as keyof typeof PART_META].label : null;
  const partModule = sp?.get("module") ?? null;
  const crumbs: ReactNode[] = !mod ? [...head, ...(trail ?? []).map((t, i) => (t.href ? <Link key={`t${i}`} className="cys-crumb" href={t.href}>{t.label}</Link> : <span key={`t${i}`} className="cys-crumb">{t.label}</span>)), <span key="s" className="cys-crumb on" aria-current="page">{icon}{current}</span>] : [
    ...head,
    <Link key="c" className="cys-crumb" href="/dashboard/cyrus"><span style={{ color: `rgb(${c.rgb})`, display: "flex", fontSize: 14 }}><CategoryIcon k={c.key} /></span>{c.label}</Link>,
    <Link key="m" className="cys-crumb" href={assetsHref(mod!)}><span className="cys-dot" style={{ background: `rgb(${c.rgb})`, boxShadow: `0 0 8px rgb(${c.rgb})` }} /><span style={{ maxWidth: 180, overflow: "hidden", textOverflow: "ellipsis" }}>{mod.name}</span></Link>,
    ...(part ? [<span key="p" className="cys-crumb" data-part={partKey}>{part}{partModule ? `: ${partModule.replace(/_/g, " ")}` : ""}</span>] : []),
    <span key="s" className="cys-crumb on" aria-current="page">{icon ?? <SI n={studio === "sound" ? "wave" : studio === "model" ? "cube" : studio === "config" ? "gauge" : "image"} />}{current}</span>,
  ];
  return (
    <ToastCtx.Provider value={show}>
      <div className="cys" data-studio={kind ?? studio ?? "plans"}>
        <header className="cys-top">
          <Link href="/dashboard/cyrus" className="cys-brand" aria-label="Cyrus home">
            <CyrusWordmark height={19} className="topbar-logo" />
            <small>Mod Forge</small>
          </Link>
          <nav className="cys-crumbs cys-soft" aria-label="Location">
            {crumbs.map((x, i) => <Fragment key={i}>{i > 0 && <SI n="chevR" />}{x}</Fragment>)}
          </nav>
          <div className="cys-tbr">
            {seg}
            {!seg && studio && mod && (
              <div className="cys-seg cys-soft hide-n" aria-label="Studio">
                {studioShown(mod, "texture") && <Link href={studioHref(mod, "texture")} className={studio === "texture" ? "on" : ""} aria-current={studio === "texture" ? "page" : undefined}><SI n="image" />Texture</Link>}
                {studioShown(mod, "sound") && <Link href={studioHref(mod, "sound")} className={studio === "sound" ? "on" : ""} aria-current={studio === "sound" ? "page" : undefined}><SI n="wave" />Sound</Link>}
                {(showModel || studio === "model") && studioShown(mod, "model") && <Link href={studioHref(mod, "model")} className={studio === "model" ? "on" : ""} aria-current={studio === "model" ? "page" : undefined}><SI n="cube" />Model</Link>}
                {(showConfig || studio === "config") && studioShown(mod, "config") && <Link href={studioHref(mod, "config")} className={studio === "config" ? "on" : ""} aria-current={studio === "config" ? "page" : undefined}><SI n="gauge" />Config</Link>}
              </div>
            )}
            {mod && <Link className="cys-chip cys-soft hide-n" href={assetsHref(mod)}><SI n="package" />Mod assets</Link>}
            <span className="hide-n"><CyrusTokenChip compact beta={false} /></span>
            <ThemeButton />
          </div>
        </header>
        {children}
        {toast && (
          <div key={toast.id} className={`cys-toast ${toast.err ? "err" : ""}`} role="status">
            <SI n={toast.err ? "warn" : "check"} /><span>{toast.msg}</span>
          </div>
        )}
      </div>
    </ToastCtx.Provider>
  );
}
