// SFX audition rules (pure, client-safe). One place that says WHO may hear WHAT before applying a sound:
//   - generated sound sets and the account's own uploads are ALWAYS playable (synth layers render in the browser with
//     the same pure DSP as the render host; no network, no model call);
//   - LIBRARY audio is only ever heard through the gated preview routes (never a direct file), and only when the
//     existing gate says so: CYRUS_SOUND_LIBRARY_CLEARED for the owner's proprietary SFX library, the plan gate
//     (Saka and up) for every library tier. Not cleared -> the row shows its waveform outline and one reason line.
// This module changes no gate and reads no flag: callers pass what the server already decided.
import { canAsset } from "../engine-core/asset-gate";

/** A preview never plays longer than this (matches PREVIEW_MAX_SECONDS of the render-host preview job). */
export const PREVIEW_CAP_S = 6;

export type LibraryTier = "cc0" | "cc-by" | "proprietary-nxeon" | "user-contributed" | string;
export type AuditionVia = "synth" | "file" | "library-preview";
export type Audition = { ok: true; via: AuditionVia; note: string | null } | { ok: false; reason: string; outline: boolean };

export type AuditionInput = {
  /** where the asset came from */
  source: "generated" | "uploaded" | "library" | "imported" | "community";
  /** library tier of the entry (library / community rows) */
  tier?: LibraryTier | null;
  /** catalogue status: a held or removed asset is never auditioned from the library */
  status?: "ok" | "held" | "removed";
  /** the owner's licence clearance (CYRUS_SOUND_LIBRARY_CLEARED), decided by the server */
  proprietaryCleared: boolean;
  /** the viewer's plan (unknown = no library audio) */
  plan: unknown;
  /** staff views are not plan-gated (they never apply a sound), but never bypass the licence clearance */
  staff?: boolean;
};

/** Pure decision for ONE sound asset row. */
export function auditionFor(i: AuditionInput): Audition {
  if (i.source === "generated" || i.source === "uploaded" || i.source === "imported") {
    return { ok: true, via: i.source === "uploaded" ? "file" : "synth", note: null };
  }
  // library / community
  if (i.status === "removed") return { ok: false, reason: "This library sound was removed upstream; your mod keeps its own copy.", outline: true };
  if (i.status === "held") return { ok: false, reason: "This library sound is on hold for review, so it can't be auditioned.", outline: true };
  if (i.tier === "proprietary-nxeon" && !i.proprietaryCleared) {
    return { ok: false, reason: "Library audition is off until the owner confirms the sound licence.", outline: true };
  }
  if (!i.staff) {
    const d = canAsset(i.plan, "sound", "create");
    if (!d.ok) return { ok: false, reason: d.reason.replace("Creating or editing", "Auditioning"), outline: true };
  }
  return { ok: true, via: "library-preview", note: "A short processed preview from the gated library route." };
}

/** Cap PCM to the preview length (never plays or decodes more than PREVIEW_CAP_S). */
export function capPcm<T extends { length: number; slice(a: number, b?: number): T }>(pcm: T, sampleRate: number, seconds = PREVIEW_CAP_S): T {
  const max = Math.max(1, Math.floor(sampleRate * seconds));
  return pcm.length > max ? pcm.slice(0, max) : pcm;
}

/** "1.2 s" / "340 ms" / "" when unknown. */
export function durationLabel(s: number | null | undefined): string {
  if (s === null || s === undefined || !Number.isFinite(s) || s <= 0) return "";
  return s < 1 ? `${Math.round(s * 1000)} ms` : `${s < 10 ? s.toFixed(1) : Math.round(s)} s`;
}

/**
 * Which library sources the EXISTING rules would let a Saka-or-higher viewer audition without any new flag:
 * CC0 / CC-BY / community tiers (plan gate only) are served as preview-ogg by the v2 library route; the owner's
 * proprietary SFX library needs CYRUS_SOUND_LIBRARY_CLEARED. The legacy Sound Studio route (`sound/preview`, the owner
 * library "builtin" source) is entirely behind that flag.
 */
export function clearedLibrarySources(proprietaryCleared: boolean): { tier: string; audible: boolean; why: string }[] {
  return [
    { tier: "cc0", audible: true, why: "CC0: served as a preview to the sound-library plan (Saka and up)" },
    { tier: "cc-by", audible: true, why: "CC-BY rows are excluded from the community library; a preview would pass the plan gate if any were published" },
    { tier: "user-contributed", audible: true, why: "community contributions (CC0 only) pass the plan gate once published" },
    { tier: "proprietary-nxeon", audible: proprietaryCleared, why: "owner SFX library: needs CYRUS_SOUND_LIBRARY_CLEARED=1 (owner licence decision)" },
  ];
}

